const listPublishedMakers = `-- name: ListPublishedMakers :many
SELECT
    m.id,
    m.name,
    m.city,
    m.verification_date,
    m.moq_quantity,
    m.moq_basis,
    m.moq_basis_note,
    m.lead_time_estimate,
    m.price_min_idr,
    m.price_max_idr,
    m.price_note
FROM makers m
WHERE m.publication_status = 'published'
  AND m.is_demo_fixture = FALSE
  AND (
      $1::text IS NULL
      OR EXISTS (
          SELECT 1 FROM maker_capabilities c
          WHERE c.maker_id = m.id AND c.category_slug = $1
      )
  )
ORDER BY m.name
`

